import sys
import math

def main():
    R = int(sys.stdin.readline())
    R_squared = R * R
    count = 0
    max_i = int(math.isqrt(R_squared - 1))
    for i in range(-max_i, max_i + 1):
        for j in range(-max_i, max_i + 1):
            if i**2 + j**2 + 1 <= R_squared:
                count += 1
    print(count)

if __name__ == "__main__":
    main()

