pred_answer:
A = list(map(int, input().split()))
sorted_A = [1, 2, 3, 4, 5]
diff = [a != b for a, b in zip(A, sorted_A)]
if sum(diff) == 2 and diff[0] == False and diff[4] == False:
    # Check if swapping the two differing positions would sort the array
    # Find the indices where the difference is True
    i = 0
    j = 0
    for k in range(5):
        if diff[k]:
            i = k
            break
    for k in range(4, -1, -1):
        if diff[k]:
            j = k
            break
    # Swap i and j and check if it's sorted
    temp = A.copy()
    temp[i], temp[j] = temp[j], temp[i]
    if temp == sorted_A:
        print("Yes")
    else:
        print("No")
else:
    print("No")

